def ok(name,value=True):
 if not value:raise AssertionError(name)
 checks.append({'name':name,'passed':True});print('PASS',name,flush=True)
def launch(browser,w=1920,h=1080):
 page=browser.new_page(viewport={'width':w,'height':h},device_scale_factor=1)
 page.set_default_timeout(6000);errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
 page.route('**/*',lambda route:route.abort());mount_offline(page);install_module_loader(page)
 page.wait_for_function('document.documentElement.dataset.duoReady==="true"',timeout=25000);page.wait_for_timeout(450)
 return page,errors
