 inside=lambda r:r['left']>=-1 and r['top']>=-1 and r['right']<=samples['view']['width']+1 and r['bottom']<=samples['view']['height']+1
 bad=[{'ms':s['ms'],'boxes':{k:v for k,v in s['boxes'].items() if not inside(v)},'controls':[v for v in s['controls'] if not inside(v)],'bankInChassis':s['bankInChassis'],'content':s['content']} for s in samples['samples'] if not all(inside(r) for r in s['boxes'].values()) or not all(inside(r) for r in s['controls']) or not s['bankInChassis'] or not s['contentInsideBank']]
