def exercise_orientation_interruptions(page):
 result=page.evaluate(r"""async()=>{
  const root=document.querySelector('#duo'),chassis=root.querySelector('.duo-stage>.duo-chassis'),button=root.querySelector('.duo-orientation-button'),rect=()=>{const r=chassis.getBoundingClientRect();return [r.left,r.top,r.width,r.height]},frame=()=>new Promise(requestAnimationFrame);
  const settled=async()=>{const start=performance.now();do{await frame();}while((root.classList.contains('duo-folding')||root.classList.contains('duo-orientation-turning'))&&performance.now()-start<4000);};
  const app=window.__foldLiveApp,input=window.__foldInput;
  button.click();const first=chassis.getAnimations()[0];
  for(const animation of root.getAnimations({subtree:true})){animation.pause();animation.currentTime=180;}
  await frame();const before=rect();button.click();const reverse=chassis.getAnimations()[0];reverse.pause();reverse.currentTime=0;await frame();const after=rect();
  const from=reverse.effect.getKeyframes()[0].transform,copy=root.querySelector('.duo-orientation-copy');
  const safe=!!copy&&copy.inert&&copy.getAttribute('aria-hidden')==='true'&&!copy.querySelector('audio,video,iframe,script,object,embed');
  const identity=root.querySelector('.duo-app-instance[data-app=facetime]')===app&&input.value==='Fold draft retained';
  reverse.play();await reverse.finished;await frame();
  const cleaned=!root.classList.contains('duo-orientation-turning')&&!root.querySelector('.duo-orientation-copy');
  button.click();const turn=chassis.getAnimations()[0];PeakDuo.fold();const queued=PeakDuo.getState().workspace.expanded&&root.classList.contains('duo-orientation-turning');await turn.finished;await settled();
  const foldDiagnostic={state:PeakDuo.getState(),classes:root.className,animations:root.getAnimations({subtree:true}).map(a=>({time:a.currentTime,state:a.playState,duration:a.effect.getTiming().duration}))};const folded=!PeakDuo.getState().workspace.expanded&&!root.classList.contains('duo-folding')&&!root.querySelector('.duo-orientation-copy');
  PeakDuo.fold();await settled();
  if(root.dataset.orientation!=='landscape'){button.click();await chassis.getAnimations()[0].finished;await frame();}
  PeakDuo.setPhoneSetting('motion',true);button.click();const reduced=root.dataset.orientation==='portrait'&&!root.classList.contains('duo-orientation-turning')&&!root.querySelector('.duo-orientation-copy')&&chassis.getAnimations().length===0;button.click();PeakDuo.setPhoneSetting('motion',false);
  button.click();window.dispatchEvent(new Event('resize'));const resized=!root.classList.contains('duo-orientation-turning')&&!root.querySelector('.duo-orientation-copy');button.click();await chassis.getAnimations()[0].finished;await frame();
  button.click();PeakDuo.sendPreview({Action:'Duo/IdentityChanging'});const privateCopyCleared=!root.querySelector('.duo-orientation-copy')&&!root.classList.contains('duo-orientation-turning');
  button.click();await chassis.getAnimations()[0].finished;await frame();
  return {foldDiagnostic,before,after,from,safe,identity,cleaned,queued,folded,reduced,resized,privateCopyCleared,finalIdentity:root.querySelector('.duo-app-instance[data-app=facetime]')===app&&input.value==='Fold draft retained'};
 }""")
 print('Orientation interruption diagnostics:',json.dumps(result),flush=True)
 ok('Rapid orientation reversal continues from the current physical rectangle',max(abs(a-b) for a,b in zip(result['before'],result['after']))<1)
 import re
 angle=float(re.search(r'rotate\(([-.0-9]+)deg\)',result['from']).group(1))
