 if failed:print('HARDWARE SEMANTIC ENDPOINTS',label,json.dumps(failed),flush=True)
 ok(label+': copied hardware matches each live source/target edge, dimensions and painted axis at '+', '.join(f'{ms}ms' for ms in times),not failed)
